/bin/bash -lc "python - <<'PY'
from pathlib import Path
from openpyxl import load_workbook
ws=load_workbook('inputs/230215_Trio_Status.xlsx',data_only=True).active
meta={str(ws.cell(r,1).value).strip(): str(ws.cell(r,4).value).strip() for r in range(2,ws.max_row+1) if ws.cell(r,1).value is not None}
files={p.stem.split('CHIP_',1)[1].split('-',1)[0] for p in Path('inputs/CHIP_DP10_GQ20_PASS').glob('*.xlsx')}
print('MISSING_FILE_METADATA')
for sid in sorted(set(meta)-files): print(sid,meta[sid])
print('EXTRA_FILE_IDS')
for sid in sorted(files-set(meta)): print(sid)
PY"

